  if (kind === 'grid') { let l = ''; for (let i = 1; i < 10; i++) l += `<path d="M${i * 30} 0V300M0 ${i * 30}H300" stroke="${a}" stroke-opacity=".18"/>`; return `<svg viewBox="0 0 300 300" aria-hidden="true">${g}${l}<circle cx="150" cy="150" r="96" fill="url(#gb)"/><circle cx="150" cy="150" r="120" fill="none" stroke="${a}" stroke-opacity=".5" stroke-dasharray="4 8"/></svg>`; }
